/** Offline mode only has these two runs; map a scenario to its fixture. */
export function fixtureFor(punctureUm: number): TelemetryFrame[] | null {
  if (punctureUm === 0) return fixtures.sealed;
  if (punctureUm === 100) return fixtures.leak100;
  return null;
}
